import{_ as d,o as e,c as o,ag as r}from"./chunks/framework.C9sp7nFj.js";const S=JSON.parse('{"title":"MovL 直线运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovL.md","filePath":"3. 指令/1. 运动指令/MovL.md","lastUpdated":1778862643000}'),a={name:"3. 指令/1. 运动指令/MovL.md"};function c(O,t,i,l,n,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="movl-直线运动" tabindex="-1">MovL 直线运动 <a class="header-anchor" href="#movl-直线运动" aria-label="Permalink to &quot;MovL 直线运动&quot;">​</a></h1><p>MovL 指令为直线运动指令，通过该指令可以使机器人 TCP 点以设定的速度直线运动到目标位置。若运动的起止姿态不同，则运行过程中姿态随位置同步地旋转到终点的姿态。与 MovJ 相同，在执行完该指令时可以附加进行 IO 操作。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovL(P, [V], [B], [C], [Tool], [Coord], [PayLoad], [O], [CTV], [DO])</p><p>MovL(目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], [姿态控制], [连续轨迹速度], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的目标点位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>用于指定机器人执行 MovL 时的速度，包括机器人末端的平移速度、旋转速度以及外部轴的移动速度等。SPEED 变量中的 <code>tcp</code>、<code>ori</code> 分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式：<br><code>FINE</code>：无过渡。<br><code>RELATIVE</code>：相对过渡。<br><code>ABSOLUTE</code>：绝对过渡。<br><code>DEFAULT</code>：缺省类型。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / EXTTCP 变量 / 变位机变量</td><td>机器人执行该轨迹时使用的用户坐标系 / 外部 TCP 坐标系 / 变位机坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：本段轨迹受全局速度倍率影响。<br><code>GOVROFF</code>：本段轨迹不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[CTV]</td><td>CTV 变量</td><td>机器人无限旋转轴与无限旋转速度。</td><td>可选，默认不开启无限旋转</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后，可触发的 IO 操作，目前支持的 IO 指令有：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table>',9)])])}const m=d(a,[["render",c]]);export{S as __pageData,m as default};
